import json
import os
import re
import zipfile
import xml.etree.ElementTree as ET

# Load JSON data
with open('/root/training_feedback.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print("Loaded JSON data:")
for k, v in data.items():
    print(f"  {k}: {v}")

# Prepare transformed values
transformed = {}
for key, value in data.items():
    if key == '참석자수':
        # Digits only
        transformed[key] = re.sub(r'\D', '', value)
    elif key == '만족도':
        # Extract numeric score and format
        m = re.search(r'([0-9.]+)', str(value))
        if m:
            score = m.group(1)
            transformed[key] = f"{score}점 (5.0점 만점)"
        else:
            transformed[key] = value
    elif key == '종합의견':
        transformed[key] = value + ' 후속 심화반 검토 요망.'
    else:
        transformed[key] = value

print("\nTransformed values:")
for k, v in transformed.items():
    print(f"  {k}: {v}")
"}

