import zipfile
import os

output_path = '/root/training_feedback_ready.hwpx'

# 1. Validate it's a valid ZIP
try:
    with zipfile.ZipFile(output_path, 'r') as z:
        bad = z.testzip()
        if bad is None:
            print("Valid ZIP: OK")
        else:
            print(f"ZIP error in {bad}")
except Exception as e:
    print(f"ZIP validation failed: {e}")

# 2. Confirm no placeholders remain
placeholder_count = 0
with zipfile.ZipFile(output_path, 'r') as z:
    for name in z.namelist():
        content = z.read(name).decode('utf-8', errors='replace')
        if '{{' in content or '}}' in content:
            placeholder_count += content.count('{{')
            print(f"Found placeholder in {name}")

print(f"Remaining '{{' count: {placeholder_count}")

# 3. Spot-check substituted values
with zipfile.ZipFile(output_path, 'r') as z:
    full_text = ''
    for name in z.namelist():
        full_text += z.read(name).decode('utf-8', errors='replace')

if '후속 심화반 검토 요망' in full_text:
    print("Spot-check '후속 심화반 검토 요망': FOUND")
else:
    print("Spot-check '후속 심화반 검토 요망': MISSING")

if '점 (5.0점 만점)' in full_text:
